    public List<string> MeasurementInstrumentationIDs { get; set; }

    /// <summary>
    /// The relationship to the vertical CRS defining the absolute reference surface. If both the vertical and horizontal CRS are the same, then the vertical CRS should instead be captured only in the AbstractSpatialLocation.
    /// </summary>
    [RegularExpression(@"^[\w\-\.]+:reference-data\-\-CoordinateReferenceSystem:[\w\-\.\:\%]+:[0-9]*$")]
    [JsonPropertyName("VerticalCoordinateReferenceSystemID")]
    public string VerticalCoordinateReferenceSystemID { get; set; }

    /// <summary>
    /// The topographic information utilised in this survey, for example, Shuttle Radar Topography Mission (SRTM) v3.
    /// </summary>
    [JsonPropertyName("ExternalTopographicalInformation")]
    public string ExternalTopographicalInformation { get; set; }

    /// <summary>
    /// The average flying height for this airborne platform survey.
    /// </summary>
    [JsonPropertyName("AverageFlyingHeight")]
    public double? AverageFlyingHeight { get; set; }

}
